css:
.tg { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 2.5rem clamp(1.5rem, 4vw, 2.75rem); margin-top: 1.8rem; }
.tg__p { margin: 0; }
.tg__img { width: min(100%, 20rem); aspect-ratio: 11 / 20; border-radius: 8px; overflow: hidden; }
.tg__img picture, .tg__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.tg__n { margin: 1rem 0 .3rem; font-size: clamp(1.4rem, 1.2rem + .6vw, 1.75rem); }
.tg__r { margin: 0; font-size: .92rem; color: var(--os-color-text-muted); }
@media (max-width: 767px) { .tg { grid-template-columns: 1fr; } .tg__img { aspect-ratio: 4 / 5; } }
